$ErrorActionPreference='Stop';$c=New-Object -ComObject ADODB.Connection;$c.Open("Provider=Search.CollatorDSO;Extended Properties='Application=Windows';");$rs=$c.Execute("SELECT TOP 5000 System.ItemPathDisplay FROM SYSTEMINDEX WHERE System.FileName = 'project.assets.json' OR System.FileExtension = '.sln' OR System.FileExtension = '.slnx' OR System.FileExtension = '.csproj'");$o=New-Object System.Collections.Generic.List[string];while(-not $rs.EOF){ $o.Add([string]$rs.Fields.Item(0).Value); $rs.MoveNext() };$rs.Close();$c.Close();$o -join "`n"